/**
 * Wire-shape format types — control how a field's value is displayed
 * (currency / percent / decimal places for numeric fields; QR codes
 * for text/handle fields; reference wrappers for picklist fields).
 *
 * One type per format kind serves both directions on the wire:
 * compose-side input bodies and pull-side response payloads share the
 * same shape, so a single declaration covers both.
 *
 * Mirrors ultron's:
 *   - `AspectNumericFieldFormatInput` / `AspectNumericFieldFormat`
 *     (`shared/.../fieldformat/input/`)
 *   - `AspectReferenceFieldFormatInput` / `AspectReferenceFieldFormat`
 *   - `AspectFieldQrFormatInput` / `AspectFieldQrFormat`
 *   - `Currency` enum (`shared/.../fieldformat/Currency.java`)
 */
/**
 * ISO-4217 currency codes ultron supports for numeric formatting.
 * Mirrors ultron's `Currency` enum.
 */
export type CurrencyCode = "USD" | "EUR" | "JPY" | "GBP" | "AUD" | "CAD" | "CHF" | "CNY" | "SEK" | "MXN" | "NZD" | "SGD" | "HKD" | "NOK" | "KRW" | "TRY" | "INR" | "RUB" | "BRL" | "ZAR" | "DKK" | "PLN" | "TWD" | "THB" | "MYR";
/**
 * Numeric field format — controls how decimal / number /
 * calculated-numeric fields render. Each option is independent (e.g.
 * setting `currency` does not preclude `delimiter`); ultron applies
 * the format only to fields whose type is in the "compatible types"
 * set, otherwise the existing format is preserved.
 *
 * Used as both the compose-side input body slot and the pull-side
 * response slot (`AspectFieldPullResponse.numericFormat`).
 */
export interface AspectNumericFieldFormat {
    /** When true, render negative values in red. */
    readonly negativeColor?: boolean;
    /** Render with a currency prefix (e.g. "$1,000"). */
    readonly currency?: CurrencyCode;
    /** When true, group thousands with the locale delimiter. */
    readonly delimiter?: boolean;
    readonly decimalPlaces?: number;
    readonly scientificNotation?: boolean;
    /** Render negatives in parentheses (accounting style). */
    readonly accountingNotation?: boolean;
    /** Multiplier applied before formatting (e.g. 100 for percent). */
    readonly multiplyBy?: number;
    /** Render as a percentage (appends "%"; pairs with `multiplyBy: 100`). */
    readonly percentage?: boolean;
}
/**
 * Reference field format — wraps a sub-format for fields whose value
 * is a reference (picklist fields). The wrapper exists so future
 * sub-formats can be added without touching every call site.
 */
export interface AspectReferenceFieldFormat {
    readonly numeric?: AspectNumericFieldFormat;
}
/**
 * QR field format — opt-in QR rendering for fields whose value is
 * encodable as a QR code (e.g. handle, text).
 */
export interface AspectFieldQrFormat {
    /** When true, ultron renders the field's value as a QR code. */
    readonly qr?: boolean;
}
